-- ExamGrind verified daily current-affairs desk: 28 October 2026.
-- Every item below is independently checked against the linked competent official release.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
$$2026-10-28-dac-capital-acquisition-aon$$, $$2026-10-28$$,
$$DAC accords Acceptance of Necessity to defence-capital proposals worth about Rs 2.12 lakh crore$$,
$$The Defence Acquisition Council (DAC) accorded Acceptance of Necessity (AoN) to capital-acquisition proposals for the armed forces at an estimated cost of about Rs 2.12 lakh crore. The official release says roughly 82% of the proposed procurement value is intended to come from Indian industry.$$,
$$This is a core defence-governance brief: it tests the difference between an AoN, which is an in-principle administrative approval, and a signed procurement contract or completed induction.$$,
$$The DAC is the Ministry of Defence’s apex acquisition decision-making body. An AoN starts the acquisition process by accepting the necessity of a proposal; subsequent procurement steps still have to occur. The 26 October approvals covered, among other systems, Army mobility, artillery, air-defence and unmanned platforms. Students should therefore not describe every listed system as already purchased or delivered.$$,
$$DAC clears capital acquisition proposals worth Rs 2.12 lakh crore for defence forces$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2328486&lang=2&reg=48$$,
$$Ministry of Defence / Press Information Bureau$$, $$2026-10-26$$,
$$["DAC stands for Defence Acquisition Council.","AoN means Acceptance of Necessity and is an in-principle administrative approval.","The approved proposals were estimated at about Rs 2.12 lakh crore.","The release says approximately 82% of the proposed procurement value is from Indian industry."]$$::jsonb,
$$[{"question":"Does an Acceptance of Necessity mean a weapon system has already been inducted?","answer":"No. It is an early acquisition approval; contracting, procurement and delivery remain separate stages."}]$$::jsonb,
$${"title":"From requirement to induction","steps":["Armed forces identify an operational requirement.","DAC grants AoN for the proposal.","Procurement and contracting follow under the acquisition process.","Equipment is delivered, tested and inducted later."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-28-ncmc-cyclone-arnab-preparedness$$, $$2026-10-28$$,
$$NCMC coordinates multi-State preparedness for Cyclone Arnab$$,
$$The National Crisis Management Committee reviewed preparedness for Cyclone Arnab in the Bay of Bengal. The official update recorded coordination with Andhra Pradesh, Odisha, Telangana, Chhattisgarh and Puducherry, alongside IMD forecasts, evacuation and shelter measures, and NDRF/SDRF readiness.$$,
$$The brief turns a live weather event into a disaster-management question: know the institutional chain from forecasting and State administration to NDRF, NDMA and restoration of essential services.$$,
$$NCMC is a high-level mechanism for coordinating responses to major crises. In this case, IMD supplied forecasts, States and the Union Territory reported local arrangements, and central agencies readied rescue, relief and maritime assets. The reported objective was zero loss of life and minimum damage; it is not a declaration that damage has already occurred.$$,
$$Cabinet Secretary chairs a meeting of National Crisis Management Committee (NCMC) to review preparedness for the impending cyclone in Bay of Bengal$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2328434&lang=1&reg=3$$,
$$Cabinet Secretariat / Press Information Bureau$$, $$2026-10-26$$,
$$["NCMC stands for National Crisis Management Committee.","IMD provided cyclone forecasts to the Committee.","The release records preparedness by Andhra Pradesh, Odisha, Telangana, Chhattisgarh and Puducherry.","NDRF and SDRF teams, district control rooms and rescue assets were placed on readiness."]$$::jsonb,
$$[{"question":"Which institution is India’s official meteorological agency in this coordination chain?","answer":"The India Meteorological Department (IMD)."}]$$::jsonb,
$${"title":"Cyclone preparedness chain","steps":["IMD issues forecast and warning inputs.","NCMC coordinates Centre-State preparedness.","States arrange shelters, evacuation and control rooms.","NDRF, SDRF and other agencies ready rescue and restoration support."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-28-ncb-operation-trident$$, $$2026-10-28$$,
$$NCB’s Operation Trident combines narcotics enforcement with financial disruption$$,
$$The Narcotics Control Bureau led Operation Trident through simultaneous action across Assam, Mizoram and Manipur against a transnational narco-financial network. The official release frames it under the Vision Document on Narcotics Control (2026–2029) and stresses a network- and finance-focused approach, not only seizure of contraband.$$,
$$This is more than an isolated seizure report. It offers a useful internal-security distinction between targeting a single consignment and dismantling logistics, facilitators, financial accounts and cross-border networks.$$,
$$The operation involved NCB coordination with State police and the Enforcement Directorate. The release says 38 multi-agency teams acted at 38 locations and describes freezing accounts and attaching allegedly illicit assets. Those figures report enforcement action, not a judicial finding of guilt; the examinable takeaway is the shift toward intelligence-led and financial-network disruption.$$,
$$NCB launches Operation Trident with simultaneous action across Assam, Mizoram and Manipur$$,
$$https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=2328181&lang=2&reg=48$$,
$$Ministry of Home Affairs / Press Information Bureau$$, $$2026-10-25$$,
$$["NCB stands for Narcotics Control Bureau.","Operation Trident involved NCB, State police and the Enforcement Directorate.","It was carried out across Assam, Mizoram and Manipur.","The official release links the approach to the Vision Document on Narcotics Control (2026–2029)."]$$::jsonb,
$$[{"question":"What is the key strategy distinction highlighted by Operation Trident?","answer":"It targets trafficking networks and their financial infrastructure, rather than focusing only on physical drug seizures."}]$$::jsonb,
$${"title":"Network-focused narcotics control","steps":["Intelligence identifies logistics and finance nodes.","Central and State agencies coordinate action.","Operations target facilitators, assets and accounts as well as contraband.","Investigation seeks to disrupt the wider transnational network."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-28-eleven-crore-farmer-ids$$, $$2026-10-28$$,
$$Digital Agriculture Mission reaches 11 crore Farmer IDs ahead of schedule$$,
$$The Ministry of Agriculture and Farmers Welfare reported that 11 crore Farmer IDs had been created under the Digital Agriculture Mission, ahead of the stated 31 March 2027 target. It describes the ID as a verified digital identity intended to simplify delivery of schemes, credit, crop insurance and disaster-relief services.$$,
$$This connects agricultural digital public infrastructure with cooperative federalism and benefit delivery. It is important to distinguish a Farmer ID from a new cash-transfer scheme or a universally automatic entitlement.$$,
$$The ministry says the Digital Agriculture Mission was approved by the Union Cabinet in September 2024. Its Farmer Registry is intended to reduce repeat verification and improve scheme administration, with implementation involving States and Union Territories. The release records a programme milestone, not proof that every farmer or every service is already fully onboarded.$$,
$$11 Crore Farmer IDs Created Five Months Ahead of Schedule, Marking Major Milestone in Digital Agriculture$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2327905&lang=1&reg=3$$,
$$Ministry of Agriculture and Farmers Welfare / Press Information Bureau$$, $$2026-10-24$$,
$$["The Farmer ID initiative is part of the Digital Agriculture Mission.","The release reports 11 crore Farmer IDs created.","The stated target date was 31 March 2027.","The system is intended to support access to schemes, bank credit, crop insurance and disaster relief."]$$::jsonb,
$$[{"question":"Is a Farmer ID itself a cash-transfer scheme?","answer":"No. It is a verified digital identity intended to make agricultural-service delivery and verification more efficient."}]$$::jsonb,
$${"title":"Farmer Registry to service delivery","steps":["A farmer receives a verified digital identity.","Records reduce repeated document verification.","Departments and States use the registry for eligible services.","Schemes, credit, insurance and relief can be delivered with better traceability."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-28-exercise-garuda-shakti-2026$$, $$2026-10-28$$,
$$India–Indonesia special-forces exercise Garuda Shakti begins in Banyuwangi$$,
$$The 11th India–Indonesia Joint Special Forces Exercise, Garuda Shakti, commenced at Banyuwangi, Indonesia. India is represented by the Parachute Regiment (Special Forces), while Indonesia is represented by its special-forces personnel.$$,
$$Joint exercises are a recurring exam area because they combine defence cooperation, partner-country identification and the operational focus of the exercise. This release specifically highlights jungle-environment special-operations training.$$,
$$The exercise runs from 27 October to 6 November 2026, according to the Ministry of Defence. Training includes tactics and procedures for jungle operations, obstacle crossing, marksmanship, mountaineering and air-assault work, with a validation exercise planned at the end. It is a bilateral training activity, not a treaty or a military deployment.$$,
$$India–Indonesia Joint Special Forces Exercise Garuda Shakti commences at Banyuwangi$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2328954&lang=1&reg=1$$,
$$Ministry of Defence / Press Information Bureau$$, $$2026-10-27$$,
$$["Garuda Shakti is an India–Indonesia joint special-forces exercise.","The 2026 edition is the 11th edition.","It is being held at Banyuwangi, Indonesia.","The Indian contingent is from the Parachute Regiment (Special Forces)."]$$::jsonb,
$$[{"question":"Which country partners India in Exercise Garuda Shakti?","answer":"Indonesia."}]$$::jsonb,
$${"title":"Bilateral exercise recall","steps":["Identify the exercise name.","Match it to the partner country.","Note the participating service or unit.","Recall the operational-training focus and venue."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-28-ngopv-srishti-launch$$, $$2026-10-28$$,
$$Next Generation Offshore Patrol Vessel Srishti launched at Goa Shipyard$$,
$$Yard 1283, named Srishti, was launched at Goa Shipyard Limited as a Next Generation Offshore Patrol Vessel for the Indian Navy. The release says the class is designed and built in India and is intended for maritime surveillance, search and rescue, offshore-asset protection, humanitarian assistance and disaster relief, and anti-piracy roles.$$,
$$This is a naval-modernisation and indigenous-shipbuilding brief. A ship launch is a construction milestone; it should not be confused with commissioning, which marks entry into operational service.$$,
$$The release identifies Goa Shipyard Limited and Garden Reach Shipbuilders and Engineers as the two yards undertaking concurrent NGOPV construction. Offshore patrol vessels have a broad constabulary and humanitarian role in addition to surveillance. Srishti’s launch therefore indicates progress in the build programme, not completion of sea trials or induction.$$,
$$Launch of Next Generation Offshore Patrol Vessel (Yard 1283, Srishti)$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2329197&lang=2&reg=48$$,
$$Ministry of Defence / Press Information Bureau$$, $$2026-10-27$$,
$$["Srishti is Yard 1283, a Next Generation Offshore Patrol Vessel.","It was launched at Goa Shipyard Limited.","NGOPVs are intended for roles including maritime surveillance, SAR, HADR and anti-piracy.","The release says NGOPVs are being constructed concurrently at GSL and GRSE."]$$::jsonb,
$$[{"question":"Does launching a naval vessel mean it has already been commissioned?","answer":"No. Launch, sea trials and commissioning are distinct stages; commissioning marks entry into service."}]$$::jsonb,
$${"title":"Shipbuilding milestones","steps":["Design and construction begin at the shipyard.","The vessel is launched into water.","Trials and equipment integration test performance.","Commissioning brings the vessel into service."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-28-india-cbd-cop17-biodiversity-statement$$, $$2026-10-28$$,
$$India links its biodiversity strategy to the Kunming–Montreal Global Biodiversity Framework at CBD COP-17$$,
$$At the CBD COP-17 high-level segment in Yerevan, India stated that its updated National Biodiversity Strategy and Action Plan translates the Kunming–Montreal Global Biodiversity Framework into 23 national targets and 142 indicators. India also called for finance, capacity building and technology transfer consistent with national circumstances.$$,
$$The item links a global biodiversity framework to domestic implementation. It is useful for questions on the Convention on Biological Diversity, national targets, access and benefit sharing, and biodiversity-related multilateral finance.$$,
$$The Convention on Biological Diversity is a multilateral environmental agreement. India’s statement addressed implementation of the Kunming–Montreal Framework, including benefit sharing from digital sequence information on genetic resources through the multilateral mechanism and Cali Fund. These are stated policy positions and implementation plans, not a new binding treaty adopted by India on the day.$$,
$$India Reaffirms Commitment to Biodiversity Conservation and Effective Implementation of Global Biodiversity Framework at CBD COP-17$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2328896&lang=2&reg=48$$,
$$Ministry of Environment, Forest and Climate Change / Press Information Bureau$$, $$2026-10-27$$,
$$["CBD COP-17 refers to the 17th Conference of the Parties to the Convention on Biological Diversity.","India’s statement was delivered at Yerevan, Armenia.","India reported 23 National Biodiversity Targets and 142 indicators in its updated strategy and action plan.","The Kunming–Montreal Global Biodiversity Framework is linked to CBD implementation."]$$::jsonb,
$$[{"question":"What does NBSAP stand for in biodiversity governance?","answer":"National Biodiversity Strategy and Action Plan."}]$$::jsonb,
$${"title":"Global biodiversity to national action","steps":["CBD provides a multilateral biodiversity framework.","Kunming–Montreal Framework sets global direction.","Countries prepare national strategies and targets.","Indicators track domestic implementation and progress."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-28-brics-parliamentary-forum-joint-declaration$$, $$2026-10-28$$,
$$12th BRICS Parliamentary Forum adopts a Joint Declaration in New Delhi$$,
$$The 12th BRICS Parliamentary Forum concluded in New Delhi with adoption of a Joint Declaration. The official text records participation by the Parliaments of BRICS members and refers to parliamentary cooperation, people-centred development, global governance, responsible technology and the Global South.$$,
$$This is a polity-and-international-relations brief: it distinguishes parliamentary diplomacy from an executive summit, and helps students identify BRICS’s expanded membership and the role of legislatures in inter-parliamentary forums.$$,
$$The Forum was held on 26–27 October 2026. The declaration lists Brazil, China, Egypt, Ethiopia, India, Indonesia, Iran, Russia, South Africa and the United Arab Emirates as BRICS member countries represented at the Forum. It says the 2027 Forum is expected under China’s BRICS chairship. A parliamentary declaration expresses shared positions; it is not legislation enacted by the Indian Parliament.$$,
$$Joint Declaration, 12th BRICS Parliamentary Forum, New Delhi, India, 26–27 October 2026$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2329065&lang=1&reg=3$$,
$$Lok Sabha Secretariat / Press Information Bureau$$, $$2026-10-27$$,
$$["The 12th BRICS Parliamentary Forum was held in New Delhi on 26–27 October 2026.","A Joint Declaration was adopted at its conclusion.","The official declaration lists ten BRICS member countries represented at the Forum.","China is identified for the 2027 BRICS chairship in the declaration."]$$::jsonb,
$$[{"question":"Is a BRICS Parliamentary Forum declaration the same as an Act passed by the Indian Parliament?","answer":"No. It is an inter-parliamentary political declaration, not domestic legislation."}]$$::jsonb,
$${"title":"Parliamentary diplomacy","steps":["Legislative representatives meet in an inter-parliamentary forum.","They discuss shared development and governance concerns.","A joint declaration records common positions.","Domestic laws still require each country’s own constitutional process."]}$$::jsonb, $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, why_it_matters = excluded.why_it_matters,
  background = excluded.background, source_title = excluded.source_title, source_url = excluded.source_url,
  source_publisher = excluded.source_publisher, source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways, quick_check = excluded.quick_check,
  visual_data = excluded.visual_data, status = excluded.status, reviewed_at = excluded.reviewed_at,
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id from public.current_affairs_briefs briefs cross join public.exams exams
where briefs.slug in (
$$2026-10-28-dac-capital-acquisition-aon$$,
$$2026-10-28-ncmc-cyclone-arnab-preparedness$$,
$$2026-10-28-ncb-operation-trident$$,
$$2026-10-28-eleven-crore-farmer-ids$$,
$$2026-10-28-exercise-garuda-shakti-2026$$,
$$2026-10-28-ngopv-srishti-launch$$,
$$2026-10-28-india-cbd-cop17-biodiversity-statement$$,
$$2026-10-28-brics-parliamentary-forum-joint-declaration$$
) and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
on conflict do nothing;

